  Future<SecureKeyCache> freshCache([
    Map<String, String> seed = const {},
  ]) async {
    final store = FakeSecureKeyStore()..map.addAll(seed);
    final cache = SecureKeyCache(store);
    await cache.probe();
    await cache.preload(store.map.keys.toList());
    return cache;
